<script setup lang="ts">
import { Archive, ArchiveRestore, Inbox, LoaderCircle, Paperclip, Pin, Search, Send, UserRound } from "lucide-vue-next";
definePageMeta({ layout: "dashboard", middleware: "auth" });
const { tr, formatDate } = useAppPreferences();
type Conversation = { id:string; isPinned:boolean; isArchived:boolean; unreadCount:number; lastMessageAt:string|null; contact:{name:string|null;phone:string;notes:string|null;tags:any}; session:{status:string;displayName:string|null}; lastMessage:{body:string|null;createdAt:string;direction:string}|null };
type Detail = Conversation & { messages:Array<{id:string;body:string|null;direction:string;status:string;createdAt:string;sentAt:string|null}> };
const search=ref(""),archived=ref(false),selectedId=ref<string|null>(null),text=ref(""),busy=ref(false),stateBusy=ref(false),error=ref("");
const {data,status,refresh}=await useFetch<{conversations:Conversation[]}>("/api/chats",{query:computed(()=>({search:search.value,archived:archived.value}))});
const conversations=computed(()=>data.value?.conversations||[]),detail=ref<Detail|null>(null);
const time=(value:string|null)=>formatDate(value,{hour:"2-digit",minute:"2-digit",month:"short",day:"numeric"});
async function select(id:string){selectedId.value=id;error.value="";try{detail.value=(await $fetch<{conversation:Detail}>(`/api/chats/${id}`)).conversation;await refresh()}catch(e:any){error.value=e.data?.statusMessage||tr("بارگذاری گفتگو ناموفق بود.","Could not load conversation.")}}
async function send(){if(!selectedId.value||!text.value.trim())return;busy.value=true;error.value="";try{await $fetch(`/api/chats/${selectedId.value}/send`,{method:"POST",body:{body:text.value}});text.value="";await select(selectedId.value)}catch(e:any){error.value=e.data?.statusMessage||tr("ارسال پیام ناموفق بود.","Message failed.")}finally{busy.value=false}}
async function changeState(values:{isPinned?:boolean;isArchived?:boolean}){if(!detail.value||stateBusy.value)return;stateBusy.value=true;error.value="";try{const result=await $fetch<{conversation:Conversation}>(`/api/chats/${detail.value.id}/state`,{method:"PATCH",body:values});detail.value={...detail.value,...result.conversation};if(values.isArchived!==undefined){detail.value=null;selectedId.value=null}await refresh()}catch(e:any){error.value=e.data?.statusMessage||tr("تغییر وضعیت گفتگو انجام نشد.","Could not update conversation.")}finally{stateBusy.value=false}}
watch([search,archived],()=>{selectedId.value=null;detail.value=null});
let timer:ReturnType<typeof setInterval>|undefined;onMounted(()=>{timer=setInterval(async()=>{await refresh();if(selectedId.value)await select(selectedId.value)},8000)});onBeforeUnmount(()=>clearInterval(timer));
</script>

<template><div><PageHeader :title="tr('گفتگوها','Conversations')" :description="tr('پیام‌های واقعی واتساپ را مدیریت و پاسخ دهید.','Manage and reply to WhatsApp messages.')"><button class="btn btn-secondary gap-2" @click="archived=!archived"><component :is="archived?Inbox:Archive" :size="17"/>{{archived?tr('صندوق ورودی','Inbox'):tr('بایگانی‌شده‌ها','Archived')}}</button></PageHeader><div v-if="error" class="mb-4 rounded-xl bg-red-50 p-3 text-sm font-bold text-red-700 dark:bg-red-950/40 dark:text-red-300">{{error}}</div><section class="surface grid min-h-[680px] overflow-hidden lg:grid-cols-[320px_1fr_260px]"><aside class="border-e"><div class="p-4"><div class="relative"><Search class="absolute start-3 top-1/2 -translate-y-1/2 text-slate-400" :size="16"/><input v-model="search" class="input py-2.5 ps-9" :placeholder="tr('جستجوی نام یا شماره','Search name or number')"></div></div><div v-if="status==='pending'" class="grid h-40 place-items-center"><LoaderCircle class="animate-spin"/></div><div v-else-if="!conversations.length" class="p-8 text-center"><Inbox class="mx-auto text-slate-300"/><p class="muted mt-3 text-sm">{{tr('گفتگویی در این بخش وجود ندارد.','There are no conversations here.')}}</p></div><button v-for="c in conversations" :key="c.id" class="flex w-full gap-3 border-t p-4 text-start hover:bg-slate-50 dark:hover:bg-slate-800" :class="selectedId===c.id?'bg-brand-50/70 dark:bg-brand-500/10':''" @click="select(c.id)"><span class="grid size-11 shrink-0 place-items-center rounded-full bg-brand-100 font-black text-brand-800">{{(c.contact.name||c.contact.phone)[0]}}</span><span class="min-w-0 flex-1"><span class="flex justify-between gap-2"><b class="truncate text-sm"><Pin v-if="c.isPinned" class="me-1 inline" :size="12"/>{{c.contact.name||c.contact.phone}}</b><small class="shrink-0 text-slate-400">{{time(c.lastMessageAt)}}</small></span><span class="mt-1 flex items-center gap-2"><small class="truncate text-slate-400">{{c.lastMessage?.body||'—'}}</small><i v-if="c.unreadCount" class="ms-auto grid size-5 shrink-0 place-items-center rounded-full bg-brand-600 text-[10px] text-white">{{c.unreadCount}}</i></span></span></button></aside><div v-if="detail" class="flex min-w-0 flex-col"><header class="flex items-center gap-3 border-b p-4"><span class="grid size-10 place-items-center rounded-full bg-brand-100 font-black">{{(detail.contact.name||detail.contact.phone)[0]}}</span><div class="min-w-0"><b class="block truncate text-sm">{{detail.contact.name||detail.contact.phone}}</b><small :class="detail.session.status==='CONNECTED'?'text-emerald-500':'text-red-400'">{{detail.session.displayName}} · {{detail.session.status}}</small></div><div class="ms-auto flex shrink-0 gap-2"><button class="icon-btn" :class="detail.isPinned?'bg-brand-50 text-brand-600':''" :disabled="stateBusy" :title="detail.isPinned?tr('برداشتن سنجاق','Unpin'):tr('سنجاق کردن','Pin')" @click="changeState({isPinned:!detail.isPinned})"><Pin :size="17"/></button><button class="icon-btn" :disabled="stateBusy" :title="detail.isArchived?tr('خارج کردن از بایگانی','Unarchive'):tr('بایگانی','Archive')" @click="changeState({isArchived:!detail.isArchived})"><component :is="detail.isArchived?ArchiveRestore:Archive" :size="17"/></button></div></header><div class="flex-1 space-y-4 overflow-auto bg-slate-50/60 p-5 dark:bg-slate-950/50"><div v-for="m in detail.messages" :key="m.id" class="flex" :class="m.direction==='OUTBOUND'?'justify-start':'justify-end'"><div class="max-w-[80%] rounded-2xl px-4 py-3 text-sm leading-7 shadow-sm" :class="m.direction==='OUTBOUND'?'rounded-es-sm bg-brand-600 text-white':'rounded-ee-sm bg-white dark:bg-slate-800'"><p>{{m.body}}</p><small class="mt-1 block opacity-60">{{time(m.sentAt||m.createdAt)}} · {{m.status}}</small></div></div></div><form class="flex gap-2 border-t p-4" @submit.prevent="send"><button type="button" class="icon-btn" disabled><Paperclip :size="18"/></button><input v-model="text" class="input" :placeholder="tr('پیام خود را بنویسید...','Write a message...')"><button class="btn btn-primary px-4" :disabled="busy||detail.session.status!=='CONNECTED'"><LoaderCircle v-if="busy" class="animate-spin" :size="18"/><Send v-else :size="18"/></button></form></div><div v-else class="grid place-items-center p-8 text-center lg:col-span-2"><div><UserRound class="mx-auto text-slate-300" :size="52"/><p class="muted mt-4">{{tr('برای مشاهده پیام‌ها یک گفتگو را انتخاب کنید.','Select a conversation to view messages.')}}</p></div></div><aside v-if="detail" class="hidden border-s p-5 lg:block"><h3 class="font-black">{{tr('اطلاعات مخاطب','Contact details')}}</h3><dl class="mt-6 space-y-5 text-sm"><div><dt class="text-slate-400">{{tr('نام','Name')}}</dt><dd class="mt-1 font-bold">{{detail.contact.name||'—'}}</dd></div><div><dt class="text-slate-400">{{tr('شماره','Phone')}}</dt><dd class="mt-1 font-mono" dir="ltr">+{{detail.contact.phone}}</dd></div><div><dt class="text-slate-400">{{tr('یادداشت','Notes')}}</dt><dd class="mt-1">{{detail.contact.notes||'—'}}</dd></div></dl></aside></section></div></template>
